const tags = `-- name: Tags :many
SELECT pipe_id, "key", value FROM pipes_tags WHERE pipe_id=? ORDER BY key
`

func (q *Queries) Tags(ctx context.Context, pipeID string) ([]PipesTag, error) {
	rows, err := q.db.QueryContext(ctx, tags, pipeID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []PipesTag{}
	for rows.Next() {
		var i PipesTag
		if err := rows.Scan(&i.PipeID, &i.Key, &i.Value); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

